import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';

function Navbar({ user, onLogout }) {
  const location = useLocation();
  const navigate = useNavigate();

  const isActive = (path) => location.pathname === path ? 'active' : '';

  const handleLogout = () => {
    onLogout();
    navigate('/');
  };

  const getLinks = () => {
    if (!user) return null;
    if (user.role === 'principal') return (
      <>
        <Link to="/principal/dashboard" className={isActive('/principal/dashboard')}>Dashboard</Link>
        <Link to="/principal/schedule" className={isActive('/principal/schedule')}>Schedule Meeting</Link>
        <Link to="/principal/blacklist" className={isActive('/principal/blacklist')}>Blacklist</Link>
      </>
    );
    if (user.role === 'hod') return (
      <>
        <Link to="/hod/dashboard" className={isActive('/hod/dashboard')}>Dashboard</Link>
        <Link to="/hod/schedule" className={isActive('/hod/schedule')}>Schedule Meeting</Link>
      </>
    );
    if (user.role === 'staff') return (
      <>
        <Link to="/staff/dashboard" className={isActive('/staff/dashboard')}>Dashboard</Link>
      </>
    );
  };

  return (
    <header className="smvit-header">
      <div className="smvit-logo-area">
        <div className="smvit-logo">SMVIT</div>
        <div>
          <div className="smvit-title">SIR M. VISVESVARAYA INSTITUTE OF TECHNOLOGY</div>
          <div className="smvit-subtitle">Affiliated to VTU, Belagavi | Approved by AICTE, New Delhi / Govt. of Karnataka | Accredited by NAAC</div>
        </div>
      </div>
      <nav className="nav-links">
        {getLinks()}
        {user && <button onClick={handleLogout}>Logout</button>}
      </nav>
    </header>
  );
}

export default Navbar;
